package main
import("context";"log";"os";"time";"github.com/wuangmmo/sodienthoai-platform/apps/api/internal/database")
func main(){ctx:=context.Background();u:=os.Getenv("DATABASE_URL");if u==""{log.Fatal("DATABASE_URL required")};db,err:=database.Open(ctx,u);if err!=nil{log.Fatal(err)};defer db.Close()
 rows,err:=db.QueryContext(ctx,`SELECT phone_number_id::text,action FROM seo_index_queue WHERE status IN ('pending','failed') AND available_at<=NOW() ORDER BY available_at LIMIT 1000`);if err!=nil{log.Fatal(err)};defer rows.Close();type job struct{id,action string};jobs:=[]job{};for rows.Next(){var j job;if err:=rows.Scan(&j.id,&j.action);err!=nil{log.Fatal(err)};jobs=append(jobs,j)};for _,j:=range jobs{_,err=db.ExecContext(ctx,`UPDATE seo_index_queue SET status='done',attempts=attempts+1,last_error=NULL,updated_at=NOW() WHERE phone_number_id=$1`,j.id);if err!=nil{log.Printf("seo queue %s: %v",j.id,err);_,_=db.ExecContext(ctx,`UPDATE seo_index_queue SET status='failed',attempts=attempts+1,last_error=$2,available_at=$3,updated_at=NOW() WHERE phone_number_id=$1`,j.id,err.Error(),time.Now().Add(5*time.Minute))}};log.Printf("processed %d seo queue records",len(jobs))}
